const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const savedPrefs=JSON.parse(localStorage.getItem('weekend-prefs')||'null');const defaultFilters={day:'全部',category:'全部',budget:'全部',district:'全部',distance:'全部',query:'',minPrice:'',maxPrice:''};const state={likes:JSON.parse(localStorage.getItem('weekend-likes')||'[]'),plans:JSON.parse(localStorage.getItem('weekend-plans-v2')||'[]'),filters:{...defaultFilters,...(savedPrefs?.filters||{})},offset:0,activePlan:0};
function money(a){return a.price===0?'免费':`¥${a.price}`}function timeToMin(t){const[h,m]=t.split(':').map(Number);return h*60+m}function persist(){localStorage.setItem('weekend-likes',JSON.stringify(state.likes));localStorage.setItem('weekend-plans-v2',JSON.stringify(state.plans));localStorage.setItem('weekend-prefs',JSON.stringify({filters:state.filters}));renderPlan();updateCounts()}function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function switchView(id){$$('.view,.nav-btn').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active');$$(`[data-view="${id}"]`).forEach(x=>x.classList.add('active'));window.scrollTo({top:0,behavior:'smooth'});if(id==='plan')renderPlan()}
function filtered(){let list=activities.filter(a=>{const f=state.filters,hasCustom=f.minPrice!==''||f.maxPrice!=='',min=f.minPrice===''?0:Number(f.minPrice),max=f.maxPrice===''?Infinity:Number(f.maxPrice);const preset=f.budget==='全部'||(f.budget==='免费'&&a.price===0)||(f.budget==='0-50'&&a.price<=50)||(f.budget==='0-100'&&a.price<=100)||(f.budget==='100-200'&&a.price>=100&&a.price<=200)||(f.budget==='200-300'&&a.price>=200&&a.price<=300)||(f.budget==='300+'&&a.price>=300);const budget=hasCustom?a.price>=min&&a.price<=max:preset;const district=f.district==='全部'||a.district===f.district;const distance=f.distance==='全部'||a.distance<=Number(f.distance);const query=(f.query||'').trim().toLowerCase(),searchText=[a.title,a.category,a.location,a.district,a.description,a.recommendReason,...a.tags].join(' ').toLowerCase();return(f.day==='全部'||a.date===f.day)&&(f.category==='全部'||a.category===f.category)&&budget&&district&&distance&&(!query||searchText.includes(query))});const day=state.filters.day==='周日'?'周日':'周六';list.sort((a,b)=>{const score=x=>day==='周日'?(x.indoor?0:1):(x.indoor?1:0);return score(a)-score(b)||a.distance-b.distance});if(list.length>6){const k=state.offset%list.length;list=[...list.slice(k),...list.slice(0,k)].slice(0,6)}return list}
function renderCards(){const list=filtered();$('#resultCount').textContent=`${list.length} 个匹配`;$('#activityGrid').style.display=list.length?'grid':'none';$('#noResults').style.display=list.length?'none':'block';$('#activityGrid').innerHTML=list.map(a=>`<article class="activity-card"><button class="like-card ${state.likes.includes(a.id)?'active':''}" data-like="${a.id}" aria-label="${state.likes.includes(a.id)?'取消想去':'加入想去'}">${state.likes.includes(a.id)?'♥':'♡'}</button><button class="card-open" data-open="${a.id}"><div class="image-wrap ${a.imageClass}"><img src="${a.image}" alt="${a.title}"><span class="venue-tag">${a.indoor?'室内':'室外'}</span></div><div class="card-body"><div class="card-kicker"><span class="category">${a.category}</span><span class="price">${money(a)}</span></div><h3>${a.title}</h3><div class="meta"><div>◷ ${a.date} ${a.startTime}–${a.endTime}</div><div>⌖ ${a.location} · 距你 ${a.distance}km</div><div class="meta-row"><span>约 ${a.duration} 小时</span><span>${a.district}区</span></div></div><p class="recommend"><b>推荐理由</b> · ${a.recommendReason}</p></div></button></article>`).join('');$$('[data-open]').forEach(b=>b.onclick=()=>openDetail(+b.dataset.open));$$('[data-like]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleLike(+b.dataset.like)})}
function openDetail(id){const a=activities.find(x=>x.id===id);if(!a)return;const liked=state.likes.includes(id),planned=state.plans.includes(id);$('#detailSheet').innerHTML=`<div class="detail-hero"><img src="${a.image}" alt="${a.title}"><button class="detail-close" aria-label="返回">×</button></div><div class="detail-content"><span class="category">${a.category} · ${a.indoor?'室内':'室外'}</span><h2>${a.title}</h2><div class="detail-facts"><div><small>时间</small>${a.date} ${a.startTime}</div><div><small>价格</small>${money(a)}</div><div><small>距离</small>${a.distance}km</div><div><small>地点</small>${a.location}</div><div><small>区域</small>${a.district}</div><div><small>预计耗时</small>${a.duration}小时</div></div><p>${a.description}</p><div class="why">✦ 为什么推荐给你：${a.recommendReason}</div><h3>适合谁</h3><div class="suitable">${a.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><div class="detail-actions"><button class="secondary ${liked?'liked':''}" data-detail-like="${id}">${liked?'♥ 已想去':'♡ 想去'}</button><button class="primary" data-detail-plan="${id}">${planned?'✓ 已加入计划':'＋ 加入计划'}</button></div>`;$('#detailSheet').classList.add('open');$('#backdrop').classList.add('open');$('.detail-close').onclick=closeDetail;$('[data-detail-like]').onclick=()=>toggleLike(id);$('[data-detail-plan]').onclick=()=>addPlan(id)}function closeDetail(){$('#detailSheet').classList.remove('open');$('#backdrop').classList.remove('open')}
function toggleLike(id){state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();renderCards();if($('#detailSheet').classList.contains('open'))openDetail(id);toast(state.likes.includes(id)?'已收藏到想去清单':'已从想去清单移除')}function addPlan(id){const a=activities.find(x=>x.id===id);if(state.plans.includes(id)){toast('已经在你的周末计划里了');return}const conflict=state.plans.map(x=>activities.find(a=>a.id===x)).find(x=>x&&x.date===a.date&&timeToMin(a.startTime)<timeToMin(x.endTime)&&timeToMin(a.endTime)>timeToMin(x.startTime));state.plans.push(id);persist();openDetail(id);toast(conflict?`已加入，但与 ${conflict.startTime} 的行程时间冲突`:`已加入你的${a.date}计划 ✓`)}function addMany(ids){ids.map(id=>activities.find(a=>a.id===id)).filter(Boolean).sort((a,b)=>a.date.localeCompare(b.date)||timeToMin(a.startTime)-timeToMin(b.startTime)).forEach(a=>{if(!state.plans.includes(a.id))state.plans.push(a.id)});persist();toast('方案已加入你的周末计划 ✓')}
function renderPlan(){const empty=!state.plans.length;$('#planEmpty').style.display=empty?'block':'none';$('#planContent').style.display=empty?'none':'block';if(empty)return;const chosen=state.plans.map(id=>activities.find(a=>a.id===id)).filter(Boolean);const groups=['周六','周日'].map(day=>({day,list:chosen.filter(a=>a.date===day)})).filter(g=>g.list.length);let conflicts=[];groups.forEach(g=>g.list.slice(1).forEach((a,i)=>{const prev=g.list[i];if(timeToMin(a.startTime)<timeToMin(prev.endTime))conflicts.push(`${a.title} 与 ${prev.startTime} 的「${prev.title}」时间冲突`)}));$('#conflictBox').innerHTML=conflicts.length?`<div class="conflict">⚠ ${conflicts[0]}</div>`:'';$('#planGroups').innerHTML=groups.map(g=>`<section class="date-group"><h2 class="date-title">${g.day} · 9月${g.day==='周六'?'19':'20'}日 <span>${g.list.length} 个安排</span></h2><div class="itinerary">${g.list.map((a,i)=>`<div class="itinerary-item"><div class="itinerary-time">${a.startTime}</div><div class="itinerary-card" data-open="${a.id}"><img src="${a.image}" alt=""><div><h3>${a.title}</h3><p>${a.location} · 约${a.duration}小时 · ${money(a)}</p></div></div><div class="item-actions"><button data-move="${a.id}" data-dir="-1" ${i===0?'disabled':''}>上移</button><button data-move="${a.id}" data-dir="1" ${i===g.list.length-1?'disabled':''}>下移</button><button class="remove" data-remove="${a.id}">删除</button></div></div>`).join('')}</div></section>`).join('');const totalHours=chosen.reduce((s,a)=>s+a.duration,0),totalPrice=chosen.reduce((s,a)=>s+a.price,0);$('#planSummary').innerHTML=`<small>周末预计</small><div class="summary-grid"><div><b>${totalHours} 小时</b><span>总时长</span></div><div><b>¥${totalPrice}</b><span>预计花费</span></div><div><b>${chosen.length}</b><span>活动数量</span></div></div>`;$$('#planGroups [data-open]').forEach(x=>x.onclick=()=>openDetail(+x.dataset.open));$$('[data-remove]').forEach(x=>x.onclick=()=>{state.plans=state.plans.filter(id=>id!==+x.dataset.remove);persist();renderCards();toast('已从周末计划删除')});$$('[data-move]').forEach(x=>x.onclick=()=>movePlan(+x.dataset.move,+x.dataset.dir))}
function movePlan(id,dir){const a=activities.find(x=>x.id===id);const group=state.plans.filter(x=>activities.find(y=>y.id===x)?.date===a.date);const pos=group.indexOf(id),target=group[pos+dir];if(!target)return;const i=state.plans.indexOf(id),j=state.plans.indexOf(target);[state.plans[i],state.plans[j]]=[state.plans[j],state.plans[i]];persist();toast('行程顺序已调整')}function updateCounts(){$('#planBadge').textContent=state.plans.length;$('#profileLikes').textContent=Math.max(5,state.likes.length);$('#profilePlans').textContent=Math.max(3,state.plans.length)}
const planTemplates=[{style:'松弛版',title:'方案 A：轻松 CityWalk',desc:'走走停停，留足休息时间',ids:[2,5,3],reason:'天气适合步行，三个地点距离较近，不需要频繁换乘。'},{style:'省钱版',title:'方案 B：零负担城市漫游',desc:'免费活动为主，把预算留给吃喝',ids:[7,3,10],reason:'活动本身都免费，路线以步行和短距离交通为主。'},{style:'探索版',title:'方案 C：艺术与城市切片',desc:'更丰富，也更有新鲜感',ids:[1,6,9],reason:'室内活动不受天气影响，内容从视觉艺术延伸到音乐。'}];
function generatePlans(){const day=$('#aiDay').value,budget=$('#aiBudget').value,pref=$('#aiPreference .selected')?.dataset.value||'relax',interests=$$('#aiInterests .selected').map(x=>x.dataset.value);let templates=planTemplates.map(x=>({...x,ids:[...x.ids]}));if(budget==='free')templates[0]={...templates[1],title:'方案 A：省钱也好玩'};else if(pref==='sport')templates[0]={style:'探索版',title:'方案 A：沿江活力路线',desc:'早起动一动，下午慢慢逛',ids:[8,7,3],reason:'晴天适合户外，步行和轻徒步的强度循序渐进。'};else if(pref==='photo')templates[0]={style:'出片版',title:'方案 A：城市镜头漫游',desc:'把最好的光线留给街区',ids:[7,6,2],reason:'三个地点都有稳定的拍照场景，时间顺序也照顾到自然光。'};else if(pref==='food')templates[0]={style:'逛吃版',title:'方案 A：咖啡与市集慢游',desc:'边走边吃，不需要赶场',ids:[10,5,3],reason:'面包、咖啡和市集串成一条轻松路线，预算也容易控制。'};const pool=activities.filter(a=>(day==='整个周末'||a.date===day)&&(!interests.length||interests.includes(a.category))).concat(activities.filter(a=>day==='整个周末'||a.date===day));templates=templates.map((t,idx)=>{const used=[];t.ids.forEach(id=>{const current=activities.find(a=>a.id===id);const valid=current&&(day==='整个周末'||current.date===day)&&(idx>0||!interests.length||interests.includes(current.category))&&!used.includes(id);const next=valid?current:pool.find(a=>!used.includes(a.id));if(next)used.push(next.id)});pool.forEach(a=>{if(used.length<3&&!used.includes(a.id))used.push(a.id)});return{...t,ids:used.slice(0,3)}});return templates}
function renderAi(plans){$('#aiResults').innerHTML=`<div class="result-top"><h2>为你生成了 3 个方案</h2><div class="plan-tabs">${plans.map((p,i)=>`<button data-plan-tab="${i}" class="${i===state.activePlan?'active':''}">${p.style}</button>`).join('')}</div></div><div id="aiPlanCard"></div>`;$('#aiResults').classList.add('show');$$('[data-plan-tab]').forEach(b=>b.onclick=()=>{state.activePlan=+b.dataset.planTab;renderAi(plans)});const p=plans[state.activePlan],items=p.ids.map(id=>activities.find(a=>a.id===id)).filter(Boolean).sort((a,b)=>timeToMin(a.startTime)-timeToMin(b.startTime)),hours=items.reduce((s,a)=>s+a.duration,0),price=items.reduce((s,a)=>s+a.price,0);$('#aiPlanCard').innerHTML=`<article class="ai-plan"><div class="ai-plan-head"><div><h3>${p.title}</h3><p>${p.desc}</p></div><span class="plan-style">${p.style}</span></div><div class="route-list">${items.map(a=>`<div class="route-item"><b class="route-time">${a.startTime}</b><button data-open="${a.id}"><b>${a.title}</b><small>${a.location} · ${a.category}</small></button><span>→</span></div>`).join('')}</div><div class="plan-metrics"><div><small>总时长</small><b>${hours} 小时</b></div><div><small>总预算</small><b>约 ¥${price}</b></div><div><small>路线范围</small><b>${[...new Set(items.map(x=>x.district))].join(' · ')}</b></div></div><p class="ai-reason">✦ ${p.reason}</p><div class="result-actions"><button class="primary" id="addAiPlan">＋ 加入我的计划</button><button class="secondary" id="swapPlan">换一个方案</button><button class="secondary" id="adjustPrefs">调整偏好</button></div></article>`;$$('#aiPlanCard [data-open]').forEach(x=>x.onclick=()=>openDetail(+x.dataset.open));$('#addAiPlan').onclick=()=>addMany(p.ids);$('#swapPlan').onclick=()=>{state.activePlan=(state.activePlan+1)%plans.length;renderAi(plans)};$('#adjustPrefs').onclick=()=>{$('.ai-builder').scrollIntoView({behavior:'smooth'});toast('偏好已保留，可以继续调整')};$('#aiResults').scrollIntoView({behavior:'smooth',block:'start'})}
function saveFilters(){localStorage.setItem('weekend-prefs',JSON.stringify({filters:state.filters}))}function setupFilters(){$$('.chips .chip').forEach(b=>{const group=b.closest('[data-filter-group]').dataset.filterGroup;b.classList.toggle('active',state.filters[group]===b.dataset.value);b.onclick=()=>{b.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.filters[group]=b.dataset.value;if(group==='budget'){state.filters.minPrice='';state.filters.maxPrice='';$('#budgetMin').value='';$('#budgetMax').value='';$('.custom-budget').classList.remove('active')}state.offset=0;saveFilters();$('#weatherHint').textContent=state.filters.day==='周日'?'☂ 周日小雨，室内展览、咖啡和演出优先':'☀ 晴天优先推荐 CityWalk、徒步和市集';renderCards()}});$('#discoverSearch').value=state.filters.query||'';$('#clearSearch').style.visibility=state.filters.query?'visible':'hidden';$('#budgetMin').value=state.filters.minPrice;$('#budgetMax').value=state.filters.maxPrice;const custom=state.filters.minPrice!==''||state.filters.maxPrice!=='';$('.custom-budget').classList.toggle('active',custom);if(custom)$$('[data-filter-group="budget"] .chip').forEach(x=>x.classList.remove('active'))}
function registerAgentTools(){const c=document.modelContext;if(!c?.registerTool)return;const reg=t=>Promise.resolve(c.registerTool(t)).catch(()=>{});reg({name:'find_weekend_activities',title:'筛选周末活动',description:'根据日期、兴趣和预算筛选上海周末活动。',inputSchema:{type:'object',properties:{day:{type:'string'},category:{type:'string'},maxPrice:{type:'number'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:({day,category,maxPrice}={})=>activities.filter(a=>(!day||a.date===day)&&(!category||a.category===category)&&(maxPrice==null||a.price<=maxPrice)).map(a=>({id:a.id,title:a.title,date:a.date,time:a.startTime,price:a.price,district:a.district}))});reg({name:'add_activities_to_weekend_plan',title:'加入周末计划',description:'将一个或多个活动加入本地周末行程。',inputSchema:{type:'object',properties:{activityIds:{type:'array',items:{type:'number'},minItems:1}},required:['activityIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({activityIds})=>{if(!activityIds.every(id=>activities.some(a=>a.id===id)))throw new Error('包含未知活动');addMany(activityIds);return{added:activityIds,planCount:state.plans.length}}})}
$$('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-nav]').forEach(b=>b.onclick=()=>switchView(b.dataset.nav));$('#backdrop').onclick=closeDetail;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});$('#shuffle').onclick=()=>{state.offset+=3;renderCards();toast('已换一批推荐')};$('#discoverSearch').oninput=e=>{state.filters.query=e.target.value;state.offset=0;$('#clearSearch').style.visibility=e.target.value?'visible':'hidden';saveFilters();renderCards()};$('#clearSearch').onclick=()=>{state.filters.query='';$('#discoverSearch').value='';$('#clearSearch').style.visibility='hidden';saveFilters();renderCards();$('#discoverSearch').focus()};function applyCustomBudget(){const min=$('#budgetMin').value,max=$('#budgetMax').value;if(min!==''&&max!==''&&Number(min)>Number(max)){toast('最低预算不能高于最高预算');return}state.filters.minPrice=min===''?'':Math.max(0,Number(min));state.filters.maxPrice=max===''?'':Math.max(0,Number(max));state.filters.budget='全部';$$('[data-filter-group="budget"] .chip').forEach(x=>x.classList.remove('active'));$('.custom-budget').classList.toggle('active',min!==''||max!=='');state.offset=0;saveFilters();renderCards();toast(min===''&&max===''?'已取消自定义预算':`已应用预算 ¥${min||0}–${max||'不限'}`)}$('#applyBudget').onclick=applyCustomBudget;[$('#budgetMin'),$('#budgetMax')].forEach(x=>x.onkeydown=e=>{if(e.key==='Enter')applyCustomBudget()});$('#resetFilters').onclick=()=>{state.filters={...defaultFilters};setupFilters();saveFilters();renderCards();toast('筛选条件已重置')};$$('[data-weather-day]').forEach(b=>b.onclick=()=>{state.filters.day=b.dataset.weatherDay;setupFilters();saveFilters();renderCards();$('#weatherHint').textContent=state.filters.day==='周日'?'☂ 周日小雨，室内展览、咖啡和演出优先':'☀ 晴天优先推荐 CityWalk、徒步和市集'});$('#aiInterests').onclick=e=>{const b=e.target.closest('button');if(b)b.classList.toggle('selected')};$('#aiPreference').onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('#aiPreference button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')};$('#aiSubmit').onclick=()=>{const btn=$('#aiSubmit');btn.disabled=true;btn.textContent='正在安排…';$('#aiResults').classList.remove('show');$('#aiLoading').classList.add('show');localStorage.setItem('weekend-ai-prefs',JSON.stringify({day:$('#aiDay').value,time:$('#aiTime').value,budget:$('#aiBudget').value,people:$('#aiPeople').value,interests:$$('#aiInterests .selected').map(x=>x.dataset.value),preference:$('#aiPreference .selected')?.dataset.value}));setTimeout(()=>{$('#aiLoading').classList.remove('show');btn.disabled=false;btn.textContent='✦ 帮我安排';state.activePlan=0;renderAi(generatePlans())},1050)};
setupFilters();renderCards();renderPlan();updateCounts();registerAgentTools();
